/**
 * Bulk-safe logic for ContactTrigger.
 *
 * Budget for an insert/update of up to 200 contacts (before + after combined):
 *   - SOQL: at most 2 (one in the before context, one in the after insert context)
 *   - DML:  at most 1 (a single account update in the after insert context)
 *
 * Declared without sharing on purpose: the original trigger ran its queries and
 * the account update in system context. Enforcing sharing here would change
 * behaviour (e.g. the account phone update could fail for users without edit
 * access to the account).
 */
public without sharing class ContactTriggerHandler {

    /**
     * Before insert / before update.
     * Defaults MailingCountry from the account's BillingCountry when blank, and
     * (on insert only) LeadSource from the account's AccountSource when blank.
     */
    public static void handleBeforeUpsert(List<Contact> newContacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry) || (isInsert && String.isBlank(c.LeadSource))) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert.
     * If an account has no phone, it takes the phone of the first new contact
     * (in trigger order) of that account that has a phone. Accounts that already
     * have a phone are left untouched. All updates are sent in one DML statement.
     */
    public static void handleAfterInsert(List<Contact> newContacts) {
        // First non-blank contact phone per account, in trigger order.
        Map<Id, String> firstPhoneByAccount = new Map<Id, String>();
        for (Contact c : newContacts) {
            if (c.AccountId != null
                && String.isNotBlank(c.Phone)
                && !firstPhoneByAccount.containsKey(c.AccountId)) {
                firstPhoneByAccount.put(c.AccountId, c.Phone);
            }
        }

        if (firstPhoneByAccount.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account a : [SELECT Id, Phone FROM Account WHERE Id IN :firstPhoneByAccount.keySet()]) {
            if (String.isBlank(a.Phone)) {
                a.Phone = firstPhoneByAccount.get(a.Id);
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
