File: force-app/main/default/classes/RecordSearchService.cls

```apex
/**
 * Backend for the admin "record finder" component.
 *
 * Security model:
 *  - "with sharing" so the running user's record sharing applies.
 *  - Object/field existence, readability, filterability and sortability are verified against
 *    the schema before any SOQL is built, so every identifier that reaches the query string
 *    is a canonical API name taken from describe results, never raw user text.
 *  - Filter values are never concatenated into the query. Non-null values are passed as
 *    named bind variables; null is emitted as the SOQL literal null.
 *  - Database.queryWithBinds(..., AccessLevel.USER_MODE) additionally enforces object and
 *    field-level security in the platform.
 *
 * Every failure path raises RecordSearchService.SearchException.
 */
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;
    private static final Integer MAX_INT_VALUE = 2147483647;

    /** Field types that can legitimately be used with an equality filter. */
    private static final Set<Schema.DisplayType> FILTER_TYPES = new Set<Schema.DisplayType>{
        Schema.DisplayType.BOOLEAN,
        Schema.DisplayType.DATE,
        Schema.DisplayType.DATETIME,
        Schema.DisplayType.TIME,
        Schema.DisplayType.ID,
        Schema.DisplayType.REFERENCE,
        Schema.DisplayType.INTEGER,
        Schema.DisplayType.LONG,
        Schema.DisplayType.DOUBLE,
        Schema.DisplayType.CURRENCY,
        Schema.DisplayType.PERCENT,
        Schema.DisplayType.STRING,
        Schema.DisplayType.PICKLIST,
        Schema.DisplayType.EMAIL,
        Schema.DisplayType.PHONE,
        Schema.DisplayType.URL
    };

    /**
     * Runs a single bulk-safe SOQL query against objectApiName.
     *
     * @param objectApiName API name of the object (case-insensitive).
     * @param fields        Field API names to return in addition to Id (case-insensitive).
     * @param filters       Field API name -> value. Each entry becomes "field = value", AND-ed.
     *                      Null/empty means no WHERE clause.
     * @param orderByField  Optional field to sort ascending. Blank means no ORDER BY.
     * @param maxRows       LIMIT, must be between 1 and 200 inclusive.
     * @return The matching records visible to the running user.
     * @throws SearchException for any validation, schema, or access failure.
     */
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            return runSearch(objectApiName, fields, filters, orderByField, maxRows);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            // Platform errors (e.g. QueryException from USER_MODE enforcement) are surfaced
            // as the documented exception type.
            throw new SearchException('Record search failed: ' + e.getMessage());
        }
    }

    // -------------------------------------------------------------------------
    // Core logic
    // -------------------------------------------------------------------------

    private static List<SObject> runSearch(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        Schema.DescribeSObjectResult objDescribe = describeObject(objectApiName);
        String objName = objDescribe.getName();
        Map<String, Schema.SObjectField> fieldMap = indexFields(objDescribe);

        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException(
                'maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.'
            );
        }

        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }

        // SELECT list: Id first, then requested fields, de-duplicated case-insensitively.
        List<String> selectNames = new List<String>{ 'Id' };
        Set<String> seen = new Set<String>{ 'id' };
        for (String name : fields) {
            Schema.DescribeFieldResult fd = readableField(fieldMap, name, objName);
            if (seen.add(fd.getName().toLowerCase())) {
                selectNames.add(fd.getName());
            }
        }

        // WHERE list: one equality condition per filter entry.
        List<String> conditions = new List<String>();
        Map<String, Object> binds = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            for (String key : filters.keySet()) {
                Schema.DescribeFieldResult fd = readableField(fieldMap, key, objName);
                if (!fd.isFilterable() || !FILTER_TYPES.contains(fd.getType())) {
                    throw new SearchException(
                        'Field ' + fd.getName() + ' on ' + objName + ' cannot be used as a filter.'
                    );
                }

                Object raw = filters.get(key);
                if (raw == null) {
                    // SOQL null literal: a constant, not user text.
                    conditions.add(fd.getName() + ' = null');
                } else {
                    String bindName = 'f' + binds.size();
                    binds.put(bindName, coerce(fd, raw));
                    conditions.add(fd.getName() + ' = :' + bindName);
                }
            }
        }

        // ORDER BY: optional, ascending.
        String orderClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult sortFd = readableField(fieldMap, orderByField, objName);
            if (!sortFd.isSortable()) {
                throw new SearchException(
                    'Field ' + sortFd.getName() + ' on ' + objName + ' cannot be sorted.'
                );
            }
            orderClause = ' ORDER BY ' + sortFd.getName() + ' ASC';
        }

        String whereClause = conditions.isEmpty()
            ? ''
            : ' WHERE ' + String.join(conditions, ' AND ');

        String query =
            'SELECT ' + String.join(selectNames, ', ') +
            ' FROM ' + objName +
            whereClause +
            orderClause +
            ' LIMIT ' + maxRows;

        return Database.queryWithBinds(query, binds, System.AccessLevel.USER_MODE);
    }

    // -------------------------------------------------------------------------
    // Schema resolution and access checks
    // -------------------------------------------------------------------------

    private static Schema.DescribeSObjectResult describeObject(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name is required.');
        }

        Schema.SObjectType sot = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sot == null) {
            throw new SearchException('Object ' + objectApiName + ' does not exist.');
        }

        Schema.DescribeSObjectResult d = sot.getDescribe();
        if (!d.isAccessible() || !d.isQueryable()) {
            throw new SearchException('The running user cannot read object ' + d.getName() + '.');
        }
        return d;
    }

    private static Map<String, Schema.SObjectField> indexFields(Schema.DescribeSObjectResult objDescribe) {
        Map<String, Schema.SObjectField> fieldMap = new Map<String, Schema.SObjectField>();
        for (Schema.SObjectField f : objDescribe.fields.getMap().values()) {
            fieldMap.put(f.getDescribe().getName().toLowerCase(), f);
        }
        return fieldMap;
    }

    /**
     * Resolves a field API name (case-insensitive) and verifies the running user can read it.
     */
    private static Schema.DescribeFieldResult readableField(
        Map<String, Schema.SObjectField> fieldMap,
        String name,
        String objName
    ) {
        if (String.isBlank(name)) {
            throw new SearchException('Field names cannot be blank.');
        }

        Schema.SObjectField sf = fieldMap.get(name.toLowerCase());
        if (sf == null) {
            throw new SearchException('"' + name + '" is not a field of ' + objName + '.');
        }

        Schema.DescribeFieldResult fd = sf.getDescribe();
        if (!fd.isAccessible()) {
            throw new SearchException('The running user cannot read field ' + fd.getName() + '.');
        }
        return fd;
    }

    // -------------------------------------------------------------------------
    // Filter value coercion (values arrive from the UI with arbitrary types)
    // -------------------------------------------------------------------------

    private static Boolean isSupportedValue(Object value) {
        return value instanceof String
            || value instanceof Boolean
            || value instanceof Date
            || value instanceof Datetime
            || value instanceof Time
            || value instanceof Decimal
            || value instanceof Integer
            || value instanceof Long
            || value instanceof Double
            || value instanceof Id;
    }

    /**
     * Converts a non-null filter value to the Apex type matching the field, so that
     * the bind variable is type-correct. Throws SearchException on any mismatch.
     */
    private static Object coerce(Schema.DescribeFieldResult fd, Object value) {
        String fieldName = fd.getName();
        if (!isSupportedValue(value)) {
            throw new SearchException('Unsupported filter value type for field ' + fieldName + '.');
        }

        Schema.DisplayType dt = fd.getType();

        if (dt == Schema.DisplayType.BOOLEAN) {
            return toBoolean(value, fieldName);
        }
        if (dt == Schema.DisplayType.DATE) {
            return toDate(value, fieldName);
        }
        if (dt == Schema.DisplayType.DATETIME) {
            return toDatetime(value, fieldName);
        }
        if (dt == Schema.DisplayType.TIME) {
            if (value instanceof Time) {
                return value;
            }
            throw mismatch(fieldName);
        }
        if (dt == Schema.DisplayType.ID || dt == Schema.DisplayType.REFERENCE) {
            return toId(value, fieldName);
        }
        if (dt == Schema.DisplayType.INTEGER) {
            return toInteger(value, fieldName);
        }
        if (dt == Schema.DisplayType.LONG
            || dt == Schema.DisplayType.DOUBLE
            || dt == Schema.DisplayType.CURRENCY
            || dt == Schema.DisplayType.PERCENT) {
            return toDecimal(value, fieldName);
        }
        if (dt == Schema.DisplayType.STRING
            || dt == Schema.DisplayType.PICKLIST
            || dt == Schema.DisplayType.EMAIL
            || dt == Schema.DisplayType.PHONE
            || dt == Schema.DisplayType.URL) {
            return String.valueOf(value);
        }

        throw new SearchException('Field ' + fieldName + ' cannot be used as a filter.');
    }

    private static SearchException mismatch(String fieldName) {
        return new SearchException('Filter value does not match the type of field ' + fieldName + '.');
    }

    private static Object toBoolean(Object value, String fieldName) {
        if (value instanceof Boolean) {
            return value;
        }
        if (value instanceof String) {
            String s = ((String) value).trim().toLowerCase();
            if (s == 'true') {
                return true;
            }
            if (s == 'false') {
                return false;
            }
        }
        throw mismatch(fieldName);
    }

    private static Object toDate(Object value, String fieldName) {
        if (value instanceof Date) {
            return value;
        }
        if (value instanceof String) {
            try {
                return Date.valueOf(((String) value).trim());
            } catch (Exception e) {
                // fall through to mismatch
            }
        }
        throw mismatch(fieldName);
    }

    private static Object toDatetime(Object value, String fieldName) {
        if (value instanceof Datetime) {
            return value;
        }
        if (value instanceof String) {
            try {
                return Datetime.valueOf(((String) value).trim());
            } catch (Exception e) {
                // fall through to mismatch
            }
        }
        throw mismatch(fieldName);
    }

    private static Object toId(Object value, String fieldName) {
        if (value instanceof Id) {
            return value;
        }
        if (value instanceof String) {
            try {
                return Id.valueOf(((String) value).trim());
            } catch (Exception e) {
                // fall through to mismatch
            }
        }
        throw mismatch(fieldName);
    }

    private static Decimal toDecimal(Object value, String fieldName) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer
            || value instanceof Long
            || value instanceof Double
            || value instanceof String) {
            try {
                return Decimal.valueOf(String.valueOf(value).trim());
            } catch (Exception e) {
                // fall through to mismatch
            }
        }
        throw mismatch(fieldName);
    }

    private static Integer toInteger(Object value, String fieldName) {
        Decimal d = toDecimal(value, fieldName);
        Decimal whole = d.setScale(0);
        if (whole != d || d > MAX_INT_VALUE || d < -MAX_INT_VALUE) {
            throw mismatch(fieldName);
        }
        return d.intValue();
    }
}
```

Notes on the design:

- **Injection safety:** object, field and order-by names are re-resolved through describe and written using their canonical API names. Non-null filter values are bound with `:fN` variables, and null becomes the literal `= null`.
- **Sharing and FLS:** the class is `with sharing`, and the query runs with `AccessLevel.USER_MODE`, so the platform enforces object/field permissions as well.
- **Error contract:** every failure raises `RecordSearchService.SearchException`. Unexpected platform exceptions are wrapped into it too.
- **Values:** values are coerced to the field's type. String inputs such as `"2024-01-15"`, `"true"`, or a 15/18-character Id are accepted and converted. Values that can't be converted raise `SearchException`.
- **Filterability:** a filter field must pass `isFilterable()` and be a scalar type that supports equality. Multi-select picklists, long text areas, and compound fields are rejected.

