public with sharing class PicklistService {

    /**
     * One active value of a picklist or multi-select picklist field.
     */
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;
    }

    /**
     * Raised for invalid input or for a metadata lookup that cannot be satisfied.
     */
    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of a picklist or multi-select picklist field,
     * in the order they are defined on the field. Inactive values are excluded.
     *
     * Object and field API names are matched case-insensitively and may be
     * standard or custom.
     *
     * @throws PicklistServiceException when a name is null or blank, the object
     *         or field does not exist, or the field is not a picklist type.
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        String objName = normaliseName(objectApiName, 'objectApiName');
        String fldName = normaliseName(fieldApiName, 'fieldApiName');

        // getGlobalDescribe() keys are lower-cased, so look up with a lower-cased name.
        Schema.SObjectType sObjType = Schema.getGlobalDescribe().get(objName.toLowerCase());
        if (sObjType == null) {
            throw new PicklistServiceException('Object not found: ' + objName);
        }

        Schema.DescribeSObjectResult objDescribe = sObjType.getDescribe();

        // Field map keys are lower-cased as well.
        Schema.SObjectField sField = objDescribe.fields.getMap().get(fldName.toLowerCase());
        if (sField == null) {
            throw new PicklistServiceException(
                'Field ' + fldName + ' not found on object ' + objName
            );
        }

        Schema.DescribeFieldResult fieldDescribe = sField.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field ' + objName + '.' + fldName + ' is not a picklist or multi-select picklist (type: '
                + String.valueOf(fieldType) + ')'
            );
        }

        List<Option> options = new List<Option>();
        // getPicklistValues() returns entries in the order defined on the field.
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (!entry.isActive()) {
                continue;
            }
            Option opt = new Option();
            opt.value = entry.getValue();
            opt.label = entry.getLabel();
            opt.isDefault = entry.isDefaultValue();
            options.add(opt);
        }
        return options;
    }

    /**
     * Rejects null and blank names and returns the trimmed name.
     */
    private static String normaliseName(String name, String paramName) {
        if (name == null || String.isBlank(name.trim())) {
            throw new PicklistServiceException(paramName + ' must not be null or blank');
        }
        return name.trim();
    }
}
