public class ErpAccountSyncJob implements Queueable {

    private static final String SYNC_DESCRIPTION = 'Synced to ERP';

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before any work so that failures are always logged and retried.
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accounts = [
            SELECT Id, Description
            FROM Account
            WHERE Id IN :accountIds
        ];

        for (Account acc : accounts) {
            acc.Description = SYNC_DESCRIPTION;
        }

        // Plain DML is all-or-nothing: a failure throws, rolls back every change in this
        // transaction, and lets the exception reach the finalizer. Deliberately not caught.
        update accounts;
    }
}
