```apex
public class ErpSyncFinalizer implements Finalizer {

    private static final String JOB_NAME = 'ErpAccountSyncJob';
    private static final String STATUS_SUCCESS = 'Success';
    private static final String STATUS_FAILED = 'Failed';
    private static final String UNKNOWN_ERROR = 'Unknown error';
    private static final Integer MAX_ERROR_LENGTH = 255;
    private static final Integer MAX_ATTEMPTS = 3;

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(FinalizerContext ctx) {
        FB_Job_Log__c logRecord = new FB_Job_Log__c(
            Job_Name__c = JOB_NAME,
            Attempt__c = attempt
        );

        if (ctx.getResult() == ParentJobResult.SUCCESS) {
            logRecord.Status__c = STATUS_SUCCESS;
            insert logRecord;
            return;
        }

        logRecord.Status__c = STATUS_FAILED;

        Exception ex = ctx.getException();
        String message = (ex != null && ex.getMessage() != null) ? ex.getMessage() : UNKNOWN_ERROR;
        logRecord.Error__c = message.length() > MAX_ERROR_LENGTH
            ? message.substring(0, MAX_ERROR_LENGTH)
            : message;

        insert logRecord;

        if (attempt < MAX_ATTEMPTS) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }
}
