```apex
/**
 * Purges FB_Integration_Log__c records on a nightly schedule.
 *
 * Retention rules:
 *   - Non-ERROR logs (DEBUG, INFO, blank, anything else) are deleted once
 *     CreatedDate is more than 30 days ago.
 *   - ERROR logs are kept until CreatedDate is more than 180 days ago.
 *
 * The scheduled entry point hands the work to a batch so that large volumes
 * are processed in chunks within governor limits.
 *
 * "without sharing" is deliberate: this is system housekeeping and must see
 * every log record regardless of the sharing context of the scheduled user.
 */
public without sharing class LogPurgeJob implements Schedulable {

    public static final String JOB_NAME = 'Log purge (nightly)';
    // Every day at 02:00 (sec min hour day-of-month month day-of-week)
    public static final String CRON_EXPRESSION = '0 0 2 * * ?';

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        Database.executeBatch(new LogPurgeBatch(), 2000);
    }

    /**
     * Schedules the nightly purge. Any existing active trigger with the same
     * job name is aborted first so that re-running this method does not create
     * duplicate schedules.
     *
     * @return the Id returned by System.schedule
     */
    public static Id scheduleNightly() {
        List<CronTrigger> existing = [
            SELECT Id
            FROM CronTrigger
            WHERE CronJobDetail.Name = :JOB_NAME
              AND State IN ('WAITING', 'ACQUIRED', 'EXECUTING', 'PAUSED', 'BLOCKED')
        ];
        for (CronTrigger ct : existing) {
            System.abortJob(ct.Id);
        }

        return System.schedule(JOB_NAME, CRON_EXPRESSION, new LogPurgeJob());
    }

    /**
     * Batch that performs the actual deletion in chunks.
     */
    public class LogPurgeBatch implements Database.Batchable<FB_Integration_Log__c> {

        public Database.QueryLocator start(Database.BatchableContext bc) {
            Datetime nonErrorCutoff = System.now().addDays(-30);
            Datetime errorCutoff = System.now().addDays(-180);

            // Note: "Level__c != 'ERROR'" alone would exclude blank (null) levels,
            // because comparisons with null never evaluate to true in SOQL.
            // The explicit null check ensures blank-level logs are purged.
            return Database.getQueryLocator([
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (CreatedDate < :nonErrorCutoff
                       AND (Level__c = null OR Level__c != 'ERROR'))
                   OR CreatedDate < :errorCutoff
            ]);
        }

        public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
            if (scope == null || scope.isEmpty()) {
                return;
            }

            Database.DeleteResult[] results = Database.delete(scope, false);
            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    for (Database.Error err : results[i].getErrors()) {
                        System.debug(LoggingLevel.ERROR,
                            'LogPurgeJob: failed to delete ' + scope[i].Id
                            + ' - ' + err.getStatusCode() + ': ' + err.getMessage());
                    }
                }
            }
        }

        public void finish(Database.BatchableContext bc) {
            System.debug(LoggingLevel.INFO, 'LogPurgeJob: purge batch finished. Job Id: ' + bc.getJobId());
        }
    }
}
