```apex
/**
 * Rolls up closed-won Opportunity Amount per Account for the current calendar year.
 *
 * - Runs in "with sharing" mode and the query runs in USER_MODE, so the running user's
 *   record sharing and field-level security are enforced.
 * - Uses a single aggregate SOQL query (SUM ... GROUP BY AccountId); opportunity rows are not loaded.
 * - Iterates the aggregate result in a FOR loop so results above the 2,000-row limit for
 *   direct list assignment of aggregate results are still supported.
 * - Every requested (non-null) Account Id is a key in the result. Accounts with no qualifying
 *   opportunities, or whose qualifying opportunities all have a blank Amount, map to 0.
 */
public with sharing class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Copy the requested Ids, dropping nulls, so that only requested Ids can become keys.
        Set<Id> requestedIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                requestedIds.add(accountId);
            }
        }

        if (requestedIds.isEmpty()) {
            return result;
        }

        // Default every requested Account to zero so no key maps to null.
        for (Id accountId : requestedIds) {
            result.put(accountId, 0);
        }

        // Single aggregate query. SUM ignores null Amount values; an account whose qualifying
        // opportunities all have blank Amount yields a null sum, which is mapped to 0 below.
        for (AggregateResult row : [
            SELECT AccountId, SUM(Amount) sumAmount
            FROM Opportunity
            WHERE AccountId IN :requestedIds
                AND IsWon = true
                AND CloseDate = THIS_YEAR
            WITH USER_MODE
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) row.get('AccountId');
            if (accountId == null || !requestedIds.contains(accountId)) {
                continue;
            }
            Decimal sumAmount = (Decimal) row.get('sumAmount');
            result.put(accountId, sumAmount == null ? 0 : sumAmount);
        }

        return result;
    }
}
```

