    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    /**
     * Valid ids and a valid discount: the selector is queried for the ids, the
     * selected records are wrapped in the domain, applyDiscount is called once with
     * the unchanged percentage and the unit of work, and only then commitWork is
     * called once.
     */
    private static void assertAppliedAndCommitted(Decimal discountPercentage) {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        IOpportunities domain = (IOpportunities) mocks.mock(IOpportunities.class);
        fflib_ISObjectUnitOfWork uow = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.Selector.setMock(selector);
        Application.Domain.setMock(domain);
        Application.UnitOfWork.setMock(uow);

        Id oppId1 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id oppId2 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Set<Id> opportunityIds = new Set<Id>{ oppId1, oppId2 };
        List<Opportunity> selected = new List<Opportunity>{
            new Opportunity(Id = oppId1, Amount = 1000.00),
            new Opportunity(Id = oppId2, Amount = 250.00)
        };

        mocks.startStubbing();
        mocks.when(selector.selectById(opportunityIds)).thenReturn(selected);
        mocks.stopStubbing();

        OpportunitiesService.applyDiscounts(opportunityIds, discountPercentage);

        ((IOpportunitiesSelector) mocks.verify(selector, 1)).selectById(opportunityIds);

        fflib_InOrder inOrder = new fflib_InOrder(mocks, new List<Object>{ domain, uow });
        ((IOpportunities) inOrder.verify(domain, 1)).applyDiscount(discountPercentage, uow);
