public class Opportunities extends fflib_SObjectDomain {

    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<SObject> sObjectList) {
        super(sObjectList);
    }

    // Insert validation
    public override void onValidate() {
        validateAmountNotNegative();
    }

    // Update validation
    public override void onValidate(Map<Id, SObject> existingRecords) {
        validateAmountNotNegative();
        validateAmountUnchangedOnWonOpportunity(existingRecords);
    }

    /**
     * Rule 1: Amount must not be negative (insert and update).
     * Pure in-memory check, no SOQL, bulk-safe.
     */
    private void validateAmountNotNegative() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    /**
     * Rule 2: On update, if the stage was already 'Closed Won' before the update,
     * the Amount may not change. Closing an opportunity as won and changing its
     * Amount in the same update is allowed because the prior stage was not won.
     * Uses the old record from the existingRecords map (Trigger.oldMap), no SOQL.
     */
    private void validateAmountUnchangedOnWonOpportunity(Map<Id, SObject> existingRecords) {
        if (existingRecords == null || existingRecords.isEmpty()) {
            return;
        }
        for (Opportunity opp : (List<Opportunity>) Records) {
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            if (oldOpp == null) {
                continue;
            }
            if (oldOpp.StageName == STAGE_CLOSED_WON && opp.Amount != oldOpp.Amount) {
                error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
            }
        }
    }

    /**
     * fflib constructor used by fflib_SObjectDomain.triggerHandler(Type).
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }
}
