        return (List<Account>) Database.query(soql);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        fflib_QueryFactory qf = newAccountQueryFactory()
            .setCondition('Id IN :accountIds');
        new ContactsSelector().addQueryFactorySubselect(qf);
        String soql = qf.toSOQL() + ' WITH USER_MODE';
        return (List<Account>) Database.query(soql);
    }

    /**
     * Base query factory with the Account base fields plus every field currently
     * on the Credit_Review field set, so admins can change that set without code changes.
     */
    private fflib_QueryFactory newAccountQueryFactory() {
        fflib_QueryFactory qf = newQueryFactory();
        Schema.FieldSet creditReview = Schema.SObjectType.Account.fieldSets.getMap().get('Credit_Review');
        if (creditReview != null) {
            qf.selectFieldSet(creditReview);
        }
        return qf;
    }
