public with sharing class AccountOnboardingService {

    public class OnboardingException extends Exception {}

    /**
     * Creates one Account per map key (named after the key) and one Contact per
     * last name in that key's list, linked to the new Account. All DML is performed
     * through a single fflib_SObjectUnitOfWork committed once.
     *
     * @param contactLastNamesByAccountName Map of Account name to Contact last names.
     * @return The inserted Accounts with Ids populated. Empty list if input is null/empty.
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> newAccounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return newAccounts;
        }

        if (!Schema.SObjectType.Account.isCreateable() || !Schema.SObjectType.Contact.isCreateable()) {
            throw new OnboardingException('The current user does not have permission to create Accounts and Contacts.');
        }

        // Account is listed first so it is committed before Contacts that reference it.
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{ Account.SObjectType, Contact.SObjectType }
        );

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account newAccount = new Account(Name = accountName);
            uow.registerNew(newAccount);
            newAccounts.add(newAccount);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null) {
                continue;
            }

            for (String lastName : lastNames) {
                Contact newContact = new Contact(LastName = lastName);
                // Relationship is resolved at commit time, once the Account has an Id.
                uow.registerNew(newContact, Contact.AccountId, newAccount);
            }
        }

        // Single commit: the UoW performs bulkified DML per SObject type and
        // populates Ids on the same Account instances held in newAccounts.
        uow.commitWork();

        return newAccounts;
    }
}
