public with sharing class OpportunityWinService {

    private static final String CLOSED_WON = 'Closed Won';

    /**
     * Closes the given opportunities (skipping any already Closed Won) and publishes
     * one Deal_Won__e per closed opportunity. Events are published only after the
     * opportunity updates have committed successfully (via the fflib unit of work).
     *
     * @return number of opportunities closed by this call
     */
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance().selectById(opportunityIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Date today = Date.today();
        Integer closedCount = 0;

        for (Opportunity opp : opportunities) {
            if (opp.StageName == CLOSED_WON) {
                continue;
            }

            opp.StageName = CLOSED_WON;
            opp.CloseDate = today;
            uow.registerDirty(opp);

            // Registered for publication only after the unit of work's DML succeeds.
            uow.registerPublishAfterSuccessTransaction(
                new Deal_Won__e(
                    Opportunity_Id__c = String.valueOf(opp.Id),
                    Amount__c = opp.Amount
                )
            );

            closedCount++;
        }

        // Single commit: updates are saved first; events are published only on success.
        // Any DML failure propagates to the caller and no Deal_Won__e is published.
        uow.commitWork();

        return closedCount;
    }
}
