public with sharing class CasePriorityHandler {

    private static final String HOT_RATING = 'Hot';
    private static final String HIGH_PRIORITY = 'High';

    /**
     * Sets Priority to 'High' on new cases whose Account has Rating = 'Hot'.
     * All other cases (including cases with no Account) are left unchanged.
     * Runs in before insert, so no DML is needed; the field values are saved with the record.
     */
    public static void setHighPriorityForHotAccounts(List<Case> newCases) {
        if (newCases == null || newCases.isEmpty()) {
            return;
        }

        // Collect the parent account Ids from the whole batch
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // One query for the whole batch, filtered to Hot accounts only
        Map<Id, Account> hotAccountsById = new Map<Id, Account>(
            [SELECT Id FROM Account WHERE Id IN :accountIds AND Rating = :HOT_RATING]
        );

        if (hotAccountsById.isEmpty()) {
            return;
        }

        // Apply the priority in memory
        for (Case c : newCases) {
            if (c.AccountId != null && hotAccountsById.containsKey(c.AccountId)) {
                c.Priority = HIGH_PRIORITY;
            }
        }
    }
}
