public with sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e platform event per Opportunity.
     *
     * All events are published with a single EventBus.publish call so that
     * bulk trigger batches (up to 200 records) stay within the per-transaction
     * publish limit. The returned SaveResult list is in the same order as the
     * input list: index i of the result corresponds to opportunities[i].
     *
     * @param opportunities  Opportunities to publish stage changes for. May be null or empty.
     * @return               One Database.SaveResult per input opportunity, in input order.
     *                       Returns an empty list when there is nothing to publish.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>(opportunities.size());
        for (Opportunity opp : opportunities) {
            events.add(buildEvent(opp));
        }

        // One publish call for the whole batch; results are returned in input order.
        return EventBus.publish(events);
    }

    /**
     * Builds the platform event payload for a single opportunity.
     * String.valueOf(Id) always yields the 18-character form, even if the Id
     * was originally supplied as 15 characters.
     */
    private static Deal_Stage_Change__e buildEvent(Opportunity opp) {
        Deal_Stage_Change__e evt = new Deal_Stage_Change__e();
        if (opp == null) {
            return evt;
        }
        evt.Opportunity_Id__c = (opp.Id == null) ? null : String.valueOf(opp.Id);
        evt.Stage__c = opp.StageName;
        evt.Amount__c = opp.Amount;
        return evt;
    }
}
