    /**
     * Sets the standard discount on new opportunity lines where the rep
     * did not enter a Discount. Lines with a Discount (including 0) are untouched.
     * Bulk-safe: one Product2 query per invocation regardless of line count.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }
        if (productIds.isEmpty()) {
            return;
