        Map<Id, String> familyByProductId = new Map<Id, String>();
        for (Product2 product : [SELECT Id, Family FROM Product2 WHERE Id IN :productIds]) {
            familyByProductId.put(product.Id, product.Family);
        }

        for (OpportunityLineItem line : lines) {
            if (line.Discount != null || line.Product2Id == null) {
                continue;
            }
            if (!familyByProductId.containsKey(line.Product2Id)) {
                continue;
            }
            line.Discount = PricingRules.standardDiscountForFamily(familyByProductId.get(line.Product2Id));
        }
    }
}
