/**
 * Sends renewal reminder emails to the owners of the given Opportunities.
 *
 * Messages are built for every opportunity first, then sent in chunks. Each
 * Messaging.sendEmail call uses allOrNone = false, so one failing recipient
 * does not stop the others, and per-message results are used to count
 * successful sends.
 */
public with sharing class RenewalReminderService {

    // Upper bound on messages handed to one Messaging.sendEmail invocation.
    private static final Integer MAX_MESSAGES_PER_CALL = 100;

    /**
     * @param opportunityIds Opportunity Ids whose renewal is due (up to 200 per job call).
     * @return The number of reminder emails that were accepted for sending successfully.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> uniqueIds = new Set<Id>();
        for (Id oppId : opportunityIds) {
            if (oppId != null) {
                uniqueIds.add(oppId);
            }
        }
        if (uniqueIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueIds
            WITH USER_MODE
        ];

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();
        for (Opportunity opp : opps) {
            messages.add(buildMessage(opp));
        }

        Integer sentCount = 0;
        for (Integer start = 0; start < messages.size(); start += MAX_MESSAGES_PER_CALL) {
            Integer finish = Math.min(start + MAX_MESSAGES_PER_CALL, messages.size());

            List<Messaging.SingleEmailMessage> chunk = new List<Messaging.SingleEmailMessage>();
            for (Integer i = start; i < finish; i++) {
                chunk.add(messages[i]);
            }

            sentCount += sendChunk(chunk);
        }

        return sentCount;
    }

    /**
     * Builds one plain-text reminder addressed to the opportunity owner (a User Id).
     */
    private static Messaging.SingleEmailMessage buildMessage(Opportunity opp) {
        String closeText = (opp.CloseDate == null) ? 'not set' : opp.CloseDate.format();

        Messaging.SingleEmailMessage msg = new Messaging.SingleEmailMessage();
        msg.setTargetObjectId(opp.OwnerId);
        msg.setSaveAsActivity(false);
        msg.setSubject('Renewal due: ' + opp.Name);
        msg.setPlainTextBody(
            'The opportunity "' + opp.Name + '" is due for renewal.\n' +
            'Close date: ' + closeText + '.\n' +
            'Please review it in Salesforce.'
        );
        return msg;
    }

    /**
     * Sends one chunk and returns how many messages were accepted successfully.
     * A whole-call exception is logged and treated as zero successes for that
     * chunk, so later chunks are still attempted.
     */
    private static Integer sendChunk(List<Messaging.SingleEmailMessage> chunk) {
        Integer ok = 0;
        try {
            List<Messaging.SendEmailResult> results = Messaging.sendEmail(chunk, false);
            for (Messaging.SendEmailResult result : results) {
                if (result.isSuccess()) {
                    ok++;
                } else {
                    for (Messaging.SendEmailError err : result.getErrors()) {
                        System.debug(LoggingLevel.ERROR,
                            'Renewal reminder failed for target ' + err.getTargetObjectId() +
                            ': ' + err.getMessage());
                    }
                }
            }
        } catch (Exception e) {
            System.debug(LoggingLevel.ERROR, 'Renewal reminder chunk send failed: ' + e.getMessage());
        }
        return ok;
    }
}
