import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';

const FIELDS = [
    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    _recordId;
    record;
    error;

    /**
     * Id of the Account to display. Provided by the record page.
     * Changing it discards the previous record/error so the spinner shows
     * until the new record is delivered by the wire adapter.
     */
    @api
    get recordId() {
        return this._recordId;
    }
    set recordId(value) {
        this._recordId = value;
        this.record = undefined;
        this.error = undefined;
    }

    /**
     * The '$recordId' expression makes the wire reactive: the adapter is
     * re-provisioned automatically whenever recordId changes.
     */
    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredRecord({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        }
    }

    get isLoading() {
        return !this.record && !this.error;
    }

    get hasRecord() {
        return !!this.record && !this.error;
    }

    get hasError() {
        return !!this.error;
    }

    get errorMessage() {
        return this.error?.body?.message ?? 'An unexpected error occurred while loading the record.';
    }

    get accountName() {
        return this.getFieldValue('Name');
    }

    get industry() {
        return this.getFieldValue('Industry');
    }

    get annualRevenue() {
        return this.getFieldValue('AnnualRevenue');
    }

    get ownerName() {
        return this.record?.fields?.Owner?.value?.fields?.Name?.value;
    }

    getFieldValue(apiName) {
