// Exact-match lookup from case status to SLDS theme class.
// A Map is used instead of a plain object so that values such as
// "constructor" or "__proto__" cannot resolve to inherited properties.
const THEME_BY_STATUS = new Map([
    ['New', 'slds-theme_info'],
    ['Escalated', 'slds-theme_error'],
    ['Closed', 'slds-theme_success']
]);

export default class CaseStatusBadge extends LightningElement {
    /**
     * Case status text to display as a badge.
     * Set by the parent component; changes are reflected reactively.
     * @type {string}
     */
    @api status;

    /**
     * True when status has a non-blank value (not null, undefined, empty or whitespace only).
     */
    get hasStatus() {
        return this.status !== null &&
            this.status !== undefined &&
            String(this.status).trim() !== '';
    }

    /**
     * CSS classes for the badge: always slds-badge, plus a theme class for known statuses.
     */
    get badgeClass() {
        const theme = THEME_BY_STATUS.get(this.status);
        return theme ? `slds-badge ${theme}` : 'slds-badge';
    }
}
