import { LightningElement, api } from 'lwc';

/**
 * Displays a list of contacts passed in by the parent component.
 * This component performs no data fetching.
 */
export default class AccountContactList extends LightningElement {
    _contacts;

    /**
     * Array of { Id, Name, Title } objects. Title is optional.
     * The parent owns this array; it is never mutated here.
     * Passing a new array reference re-renders the component.
     */
    @api
    get contacts() {
        return this._contacts;
    }
    set contacts(value) {
        this._contacts = value;
    }

    /** Contacts that are usable for rendering (non-null objects only). */
    get validContacts() {
        if (!Array.isArray(this._contacts)) {
            return [];
        }
        return this._contacts.filter(
            (contact) => contact !== null && typeof contact === 'object'
        );
    }

    get hasContacts() {
        return this.validContacts.length > 0;
    }

    get countLabel() {
        const count = this.validContacts.length;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }

    /**
     * Rows for the template, sorted by Name ascending.
     * Works on a copy so the parent's array is not reordered.
     */
    get rows() {
        return this.validContacts
            .slice()
            .sort((a, b) => toText(a.Name).localeCompare(toText(b.Name)))
            .map((contact, index) => {
                const title = toText(contact.Title);
                const id = toText(contact.Id);
                return {
                    key: `${index}-${id}`,
                    Id: id,
                    Name: toText(contact.Name),
                    Title: title,
                    hasTitle: title.trim() !== ''
                };
            });
    }
}

function toText(value) {
    return value === undefined || value === null ? '' : String(value);
}
