        this._isConnected = false;
        this.cancelPendingSearch();
        this.invalidateInFlightRequests();
    }

    get hasResults() {
        return this.contacts.length > 0;
    }

    get hasError() {
        return !!this.errorMessage;
    }

    handleSearchChange(event) {
        const searchTerm = (event.target.value || '').trim();

        // Every keystroke supersedes any pending debounced search.
        this.cancelPendingSearch();

        if (searchTerm.length < MIN_SEARCH_LENGTH) {
            // Too short: no Apex call, and discard any in-flight response.
            this.invalidateInFlightRequests();
            this.clearResults();
            return;
        }

        this._debounceTimeoutId = setTimeout(() => {
            this._debounceTimeoutId = undefined;
            this.runSearch(searchTerm);
        }, DEBOUNCE_DELAY_MS);
    }

    runSearch(searchTerm) {
        if (!this._isConnected) {
            return;
        }

        const requestId = ++this._latestRequestId;

        searchContacts({ searchTerm })
            .then(
                (result) => {
                    if (!this.isCurrentRequest(requestId)) {
                        return;
                    }
                    this.errorMessage = undefined;
                    this.contacts = result || [];
                },
                (error) => {
                    if (!this.isCurrentRequest(requestId)) {
                        return;
                    }
                    this.contacts = [];
                    this.errorMessage = this.getErrorMessage(error);
                }
            );
    }

    isCurrentRequest(requestId) {
        return this._isConnected && requestId === this._latestRequestId;
    }

    invalidateInFlightRequests() {
        this._latestRequestId += 1;
    }

    cancelPendingSearch() {
        if (this._debounceTimeoutId !== undefined) {
            clearTimeout(this._debounceTimeoutId);
            this._debounceTimeoutId = undefined;
        }
    }

    clearResults() {
        this.contacts = [];
        this.errorMessage = undefined;
    }

    getErrorMessage(error) {
        return error?.body?.message ?? error?.message ?? 'An unexpected error occurred.';
    }
}
