import FAVORITE_ADD from '@salesforce/label/c.Favorite_Add';
import FAVORITE_REMOVE from '@salesforce/label/c.Favorite_Remove';

/**
 * Icon-style toggle that marks a record as a favourite.
 *
 * - `favorite` is set by the parent and always reflects the parent's latest value.
 * - A click flips the displayed state immediately (optimistic UI) and dispatches
 *   `favoritechange` with `detail: { favorite: <new value> }`. The parent is
 *   responsible for persisting the change and may push the value back at any time.
