    get favorite() {
        return this._favorite;
    }
    set favorite(value) {
        this._favorite = Boolean(value);
    }

    get ariaPressed() {
        return this._favorite ? 'true' : 'false';
    }

    // The label describes the action a click will perform.
    get actionLabel() {
        return this._favorite ? this.labels.remove : this.labels.add;
    }

    get iconVariant() {
        return this._favorite ? 'warning' : 'base';
    }

    handleClick() {
        // Optimistic UI: flip the state shown right away.
        this._favorite = !this._favorite;

        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: this._favorite }
            })
        );
    }
