import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import LightningConfirm from 'lightning/confirm';

const OBJECT_API_NAME = 'Opportunity';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name' },
    { label: 'Stage', fieldName: 'StageName' },
    { label: 'Amount', fieldName: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' }
            ]
        }
    }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    columns = COLUMNS;

    /** Parent-supplied source array; never mutated by this component. */
    _opportunities = [];

    /** Local working copy that backs the datatable; rows are removed here after delete. */
    rows = [];

    @api
    get opportunities() {
        return this._opportunities;
    }
    set opportunities(value) {
        this._opportunities = Array.isArray(value) ? value : [];
        this.rows = [...this._opportunities];
    }

    get hasRows() {
        return this.rows.length > 0;
    }

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this.navigateToRecord(row.Id, 'view');
                break;
            case 'edit':
                this.navigateToRecord(row.Id, 'edit');
                break;
            case 'delete':
                this.handleDelete(row);
                break;
            default:
                break;
        }
    }

    navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId,
                objectApiName: OBJECT_API_NAME,
                actionName
            }
        });
    }

    async handleDelete(row) {
        let confirmed = false;
        try {
            confirmed = await LightningConfirm.open({
                message: `Are you sure you want to delete "${row.Name}"? This action cannot be undone.`,
                variant: 'header',
                label: 'Delete Opportunity'
            });
        } catch (error) {
            confirmed = false;
        }

        if (!confirmed) {
            return;
        }

        try {
            await deleteRecord(row.Id);
            this.rows = this.rows.filter((item) => item.Id !== row.Id);
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Delete failed',
                    message: this.getErrorMessage(error),
                    variant: 'error'
                })
            );
        }
    }

    getErrorMessage(error) {
        return error?.body?.message || error?.message || 'An unexpected error occurred.';
    }
}
