    handleSubmit() {
        const editors = this.editors;

        // map() (not every()/some()) so that every editor is validated and
        // all invalid lines display their messages at once.
        const results = editors.map((editor) => editor.validate());
        const allValid = results.every(Boolean);

        if (allValid) {
            this.showError = false;
            this.dispatchEvent(
                new CustomEvent('submit', {
                    detail: {
                        lines: editors.map((editor) => editor.getValue())
                    }
                })
            );
        } else {
            this.showError = true;
        }
    }
}
