import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLL_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    hasStats = false;
    errorMessage;

    _active = false;
    _inFlight = false;
    _followUp = false;
    _timerId = null;

    // Arrow-function class field: one stable reference so add/removeEventListener match.
    _handleVisibilityChange = () => {
        if (!this._active) {
            return;
        }
        if (document.visibilityState === 'visible') {
            this._startPolling();
        } else {
            this._stopTimer();
        }
    };

    connectedCallback() {
        this._active = true;
        document.addEventListener('visibilitychange', this._handleVisibilityChange);

        // Only poll while the page is visible; otherwise wait for visibilitychange.
        if (document.visibilityState === 'visible') {
            this._startPolling();
        }
    }

    disconnectedCallback() {
        this._active = false;
        this._followUp = false;
        this._stopTimer();
        document.removeEventListener('visibilitychange', this._handleVisibilityChange);
    }

    /**
     * Starts exactly one polling loop: clears any existing timer, loads
     * immediately, then refreshes every POLL_INTERVAL_MS.
     */
    _startPolling() {
        this._stopTimer();
        this._timerId = setInterval(() => this._refresh(false), POLL_INTERVAL_MS);
        this._refresh(true);
    }

    _stopTimer() {
        if (this._timerId !== null) {
            clearInterval(this._timerId);
            this._timerId = null;
        }
    }

    /**
     * @param {boolean} immediate - true for connect/visible loads, false for interval ticks.
     * Interval ticks that overlap an in-flight request are skipped. Immediate loads that
     * overlap are deferred and run once the in-flight request settles, so no two requests overlap.
     */
    async _refresh(immediate) {
        if (!this._active || document.visibilityState !== 'visible') {
            return;
        }

        if (this._inFlight) {
            if (immediate) {
                this._followUp = true;
            }
            return;
        }

        this._inFlight = true;
        try {
            const stats = await getQueueStats();
            if (this._active) {
                this.waiting = stats.waiting;
                this.longestWaitMinutes = stats.longestWaitMinutes;
                this.hasStats = true;
                this.errorMessage = undefined;
            }
        } catch (error) {
            if (this._active) {
                this.errorMessage =
                    (error && error.body && error.body.message) ||
                    (error && error.message) ||
                    'Unable to load queue statistics.';
            }
        } finally {
            this._inFlight = false;
            if (this._followUp) {
                this._followUp = false;
                this._refresh(true);
            }
        }
    }
}
