import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const BLOCKED_EMAIL_DOMAINS = new Set([
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com'
]);

const PERSONAL_EMAIL_MESSAGE = 'Use your work email address.';

export default class EventRegistrationForm extends LightningElement {
    values = {
        fullName: '',
        email: '',
        company: ''
    };

    isSubmitting = false;

    handleChange(event) {
        const field = event.target.dataset.field;
        if (Object.prototype.hasOwnProperty.call(this.values, field)) {
            this.values[field] = event.detail.value ?? '';
        }
    }

    async handleRegister() {
        if (this.isSubmitting) {
            return;
        }

        // 1. Work email rule, applied before any validity reporting.
        this.applyEmailDomainRule();

        // 2. Report validity on every input without short-circuiting,
        //    so all invalid fields show their messages at once.
        const inputs = Array.from(
            this.template.querySelectorAll('lightning-input[data-field]')
        );
        const validity = inputs.map((input) => input.reportValidity());

        // 3. Stop if any input is invalid.
        if (!validity.every(Boolean)) {
            return;
        }

        const { fullName, email, company } = this.values;
        this.isSubmitting = true;

        try {
            await register({ fullName, email, company });

            // 4. Success toast.
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            // 4. Failure toast.
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error?.body?.message,
                    variant: 'error'
                })
            );
        } finally {
            this.isSubmitting = false;
        }
    }

    applyEmailDomainRule() {
        const emailInput = this.template.querySelector(
            'lightning-input[data-field="email"]'
        );
        if (!emailInput) {
            return;
        }

        const domain = this.getEmailDomain(this.values.email);
        const message = BLOCKED_EMAIL_DOMAINS.has(domain)
            ? PERSONAL_EMAIL_MESSAGE
            : '';

        emailInput.setCustomValidity(message);
    }

    getEmailDomain(email) {
        const value = (email ?? '').trim();
        const atIndex = value.lastIndexOf('@');
