import { LightningElement, api } from 'lwc';

const HANDLED_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' ']);

let instanceCounter = 0;

/**
 * Single-select listbox following the WAI-ARIA listbox pattern.
 * DOM focus stays on the <ul role="listbox">; the active option is referenced
 * via aria-activedescendant.
 *
 * The active option is tracked by option value (not index) so that it survives
 * options being replaced by the parent.
 */
export default class StatusListbox extends LightningElement {
    /** Accessible name of the list. */
    @api label;

    _options = [];
    _selectedValue = null;
    _activeValue;
    _uid;

    constructor() {
        super();
        instanceCounter += 1;
        this._uid = instanceCounter;
    }

    /** Array of { value, label }. */
    @api
    get options() {
        return this._options;
    }
    set options(newOptions) {
        this._options = Array.isArray(newOptions)
            ? newOptions
                  .filter((option) => option && typeof option === 'object')
                  .map((option) => ({ value: option.value, label: option.label }))
            : [];

        // Keep the active option if it still exists, otherwise fall back to the
        // selected option or the first option.
        if (!this._hasOption(this._activeValue)) {
            this._activeValue = this._defaultActiveValue();
        }
    }

    /** Selected value (may be empty). Parent changes are always reflected. */
    @api
    get value() {
        return this._selectedValue;
    }
    set value(newValue) {
        this._selectedValue = newValue === undefined ? null : newValue;
        // A parent-driven change moves the active option to the new selection.
        this._activeValue = this._defaultActiveValue();
    }

    // ---- Derived state used by the template ---------------------------------

    get activeIndex() {
        const index = this._indexOfValue(this._activeValue);
        if (index >= 0) {
            return index;
        }
        return Math.max(this._indexOfValue(this._selectedValue), 0);
    }

    get activeDescendantId() {
        return this._options.length ? this._optionId(this.activeIndex) : null;
    }

    get renderedOptions() {
        const activeIndex = this.activeIndex;

        return this._options.map((option, index) => {
            const isSelected = option.value === this._selectedValue;
            const isActive = index === activeIndex;

            let className = 'slds-listbox__option slds-listbox__option_plain';
            if (isSelected) {
                className += ' slds-is-selected';
            }
            if (isActive) {
                className += ' slds-has-focus';
            }

            const id = this._optionId(index);

            return {
                key: id,
                id,
                index,
                value: option.value,
                label: option.label,
                ariaSelected: isSelected ? 'true' : 'false',
                className
            };
        });
    }

    // ---- Event handlers -----------------------------------------------------

    handleKeyDown(event) {
        const key = event.key;
        if (!HANDLED_KEYS.has(key)) {
            return; // Let every other key (notably Tab) keep its default behaviour.
        }
        event.preventDefault();

        const last = this._options.length - 1;
        if (last < 0) {
            return;
        }

        const current = this.activeIndex;

        switch (key) {
            case 'ArrowDown':
                this._setActive(Math.min(current + 1, last));
                break;
            case 'ArrowUp':
                this._setActive(Math.max(current - 1, 0));
                break;
            case 'Home':
                this._setActive(0);
                break;
            case 'End':
                this._setActive(last);
                break;
            case 'Enter':
            case ' ':
                this._commit(current);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const index = Number(event.currentTarget.dataset.index);
        this._commit(index);

        const list = this.template.querySelector('ul');
        if (list) {
            list.focus();
        }
    }

    // ---- Private helpers ----------------------------------------------------

    _optionId(index) {
        return `statusListbox-${this._uid}-option-${index}`;
    }

    _indexOfValue(value) {
        return this._options.findIndex((option) => option.value === value);
    }

    _hasOption(value) {
        return this._indexOfValue(value) >= 0;
    }

    _defaultActiveValue() {
        const selectedIndex = this._indexOfValue(this._selectedValue);
        if (selectedIndex >= 0) {
            return this._options[selectedIndex].value;
        }
        return this._options.length ? this._options[0].value : undefined;
    }

    /** Moves the active option only; does not change the selection. */
    _setActive(index) {
        const option = this._options[index];
        if (option) {
            this._activeValue = option.value;
        }
    }

    /** Makes the option active and selects it, dispatching change only if it changes. */
    _commit(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }

        this._activeValue = option.value;

        if (option.value === this._selectedValue) {
            return;
        }

        this._selectedValue = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value }
            })
        );
    }
}
