public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    /**
     * Creates one Enhanced Recurring Donation per request and returns the new Ids in request order.
     * NPSP generates the installment Opportunities itself; none are created here.
     * All requests are validated before any DML. Uses no SOQL and a single insert statement,
     * so it is bulk-safe for any batch size within DML row limits.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> newIds = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return newIds;
        }

        // Validate everything first so that no DML happens if any request is bad.
        for (Integer i = 0; i < requests.size(); i++) {
            validate(requests[i], i);
        }

        List<npe03__Recurring_Donation__c> rds = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest r : requests) {
            rds.add(buildRecurringDonation(r));
        }

        // Single DML statement for the whole batch (all-or-nothing).
        insert rds;

        for (npe03__Recurring_Donation__c rd : rds) {
            newIds.add(rd.Id);
        }
        return newIds;
    }

    private static void validate(GiftRequest r, Integer idx) {
        String prefix = 'Request at index ' + idx + ': ';

        if (r == null) {
            throw new RecurringGiftException(prefix + 'request is null.');
        }
        if (r.contactId == null) {
            throw new RecurringGiftException(prefix + 'contactId is required.');
        }
        if (r.amount == null || r.amount <= 0) {
            throw new RecurringGiftException(prefix + 'amount must be greater than zero.');
        }
        if (r.dayOfMonth == null || r.dayOfMonth < 1 || r.dayOfMonth > 31) {
            throw new RecurringGiftException(prefix + 'dayOfMonth must be between 1 and 31.');
        }
        if (r.startDate == null) {
            throw new RecurringGiftException(prefix + 'startDate is required.');
        }
        if (r.installments != null && r.installments < 0) {
            throw new RecurringGiftException(prefix + 'installments cannot be negative.');
        }
    }

    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest r) {
        Boolean openEnded = (r.installments == null || r.installments == 0);
        // The form's "31" means "last day of the month": use ERD's own last-day option.
        Boolean useLastDay = (r.dayOfMonth == 31);

        npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c(
            npe03__Contact__c = r.contactId,
            npe03__Amount__c = r.amount,
            npe03__Installment_Period__c = 'Monthly',
            npe03__Schedule_Type__c = 'Multiply By',
            npe03__Date_Established__c = r.startDate,
            npe03__Open_Ended_Status__c = openEnded ? 'Open' : 'None',
            npsp__RecurringType__c = openEnded ? 'Open' : 'Fixed',
            npsp__InstallmentFrequency__c = 1,
            npsp__Day_of_Month__c = String.valueOf(r.dayOfMonth),
            npsp__Always_Use_Last_Day_Of_Month__c = useLastDay,
            npsp__StartDate__c = r.startDate,
            npsp__Status__c = 'Active',
            npsp__PaymentMethod__c = r.paymentMethod
        );

        if (!openEnded) {
            rd.npe03__Installments__c = r.installments;
        }
        return rd;
    }
