/**
 * Splits an NPSP opportunity across General Accounting Units (GAUs) by percentage.
 *
 * Allocations are written with npsp__Percent__c only. NPSP derives npsp__Amount__c
 * from the percentage and the opportunity amount, so a later change to the
 * opportunity amount re-flows the split without further code.
 *
 * All validation runs before any data is changed. The delete and insert run in a
 * savepoint so a failed insert leaves the existing allocations untouched.
 */
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces the opportunity-level GAU allocations with one allocation per map entry.
     *
     * @param opportunityId   The opportunity to allocate.
     * @param percentByGauId  GAU Id -> percentage (60 means 60%). Totals may be below 100;
     *                        any remainder stays unallocated.
     * @return The inserted allocations, re-queried so that NPSP-calculated fields are populated.
     */
    public static List<npsp__Allocation__c> allocateByPercent(
        Id opportunityId,
        Map<Id, Decimal> percentByGauId
    ) {
        // ---- 1. Validate inputs (no DML yet) -------------------------------------------
        if (opportunityId == null) {
            throw new AllocationException('An opportunity Id is required.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU percentage is required.');
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A GAU Id in the allocation map is null.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException(
                    'Percentage for GAU ' + gauId + ' must be greater than 0.'
                );
            }
            total += pct;
        }
        if (total > 100) {
            throw new AllocationException(
                'Percentages total ' + total + '%, which exceeds 100%.'
            );
        }

        // Opportunity must exist and be visible to the running user.
        List<Opportunity> opps = [
            SELECT Id
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            LIMIT 1
        ];
        if (opps.isEmpty()) {
            throw new AllocationException(
                'Opportunity ' + opportunityId + ' was not found or is not accessible.'
            );
        }

        // Every GAU must exist, be accessible, and be active. One query for the whole map.
        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
                WITH USER_MODE
            ]
        );
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null) {
                throw new AllocationException(
                    'GAU ' + gauId + ' was not found or is not accessible.'
                );
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'GAU "' + gau.Name + '" is inactive and cannot be allocated to.'
                );
            }
        }

        // ---- 2. Build the replacement set ------------------------------------------------
        // Existing opportunity-level allocations (Payment__c null). Payment-level rows are
        // not touched. Campaign and Recurring Donation allocations never carry an
        // Opportunity lookup, so they are unaffected by this query.
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
              AND npsp__Payment__c = null
            WITH USER_MODE
        ];

        List<npsp__Allocation__c> replacements = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            replacements.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
                // npsp__Amount__c is intentionally not set. NPSP calculates it from the
                // percentage and the opportunity amount, so it stays correct when the
                // amount changes.
            ));
        }

        // ---- 3. Apply changes atomically ---------------------------------------------------
        Savepoint sp = Database.setSavepoint();
        try {
            if (!existing.isEmpty()) {
                Database.delete(existing, true, AccessLevel.USER_MODE);
            }

            Database.insert(replacements, true, AccessLevel.USER_MODE);
        } catch (DmlException e) {
            Database.rollback(sp);
            throw new AllocationException(
                'Failed to save GAU allocations: ' + e.getMessage()
            );
        }

        // ---- 4. Return the inserted rows, re-queried so NPSP-calculated fields are populated
        Set<Id> insertedIds = new Map<Id, npsp__Allocation__c>(replacements).keySet();
        return [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__General_Accounting_Unit__c,
                   npsp__Percent__c,
                   npsp__Amount__c
            FROM npsp__Allocation__c
            WHERE Id IN :insertedIds
            WITH USER_MODE
        ];
    }
}
