/**
 * Creates one NPSP household for a family registered in a single check-in.
 *
 * NPSP (Household Account model) automatically creates a single HH_Account household
 * (NPSP-generated name and greetings) when a Contact is inserted without an AccountId.
 * Inserting every new Contact in one DML would create one household per Contact, so the
 * primary contact is inserted first on its own, the household NPSP creates for it is read
 * back, and the remaining members are attached to that household in bulk.
 *
 * No record type Ids are hard-coded, the household name is never set by this class, and
 * the whole operation is wrapped in a savepoint so a failure leaves no stray accounts.
 */
public with sharing class HouseholdService {

    private static final String HOUSEHOLD_RECORD_TYPE_DEV_NAME = 'HH_Account';

    /**
     * @param members New Contacts (no Id, no AccountId). members[0] becomes the primary contact.
     * @return Id of the single NPSP household account all members belong to.
     * @throws IllegalArgumentException if members is null/empty, contains nulls, or contains
     *         Contacts that already have an Id or AccountId.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must contain at least one Contact.');
        }

        for (Contact c : members) {
            if (c == null) {
                throw new IllegalArgumentException('members must not contain null entries.');
            }
            if (c.Id != null || c.AccountId != null) {
                throw new IllegalArgumentException(
                    'members must be new Contacts with no Id and no AccountId.'
                );
            }
        }

        Savepoint sp = Database.setSavepoint();
        try {
            Contact primary = members[0];

            // Step 1: insert the primary contact alone. NPSP creates the household account
            // for it and assigns AccountId during this DML.
            insert primary;

            Id householdId = [
                SELECT AccountId
                FROM Contact
                WHERE Id = :primary.Id
                LIMIT 1
            ].AccountId;

            if (householdId == null) {
                throw new IllegalStateException(
                    'NPSP did not create a household account for the primary contact. ' +
                    'Verify the Household Account model is enabled in NPSP settings.'
                );
            }

            // Step 2: confirm the account is a real NPSP household (HH_Account record type).
            Account household = [
                SELECT Id, RecordType.DeveloperName
                FROM Account
                WHERE Id = :householdId
                LIMIT 1
            ];

            if (household.RecordType == null
                    || household.RecordType.DeveloperName != HOUSEHOLD_RECORD_TYPE_DEV_NAME) {
                throw new IllegalStateException(
                    'The account created for the primary contact is not an NPSP household ' +
                    '(expected record type ' + HOUSEHOLD_RECORD_TYPE_DEV_NAME + ').'
                );
            }

            // Step 3: attach the remaining members to the same household in one bulk DML.
            if (members.size() > 1) {
                List<Contact> others = new List<Contact>();
                for (Integer i = 1; i < members.size(); i++) {
                    members[i].AccountId = householdId;
                    others.add(members[i]);
                }
                insert others;
            }

            // Step 4: set the household's primary contact (NPSP One2One contact field).
            update new Account(
                Id = householdId,
                npe01__One2OneContact__c = primary.Id
            );

            return householdId;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }
}
