/**
 * Converts an open donation (Opportunity) into an installment plan of unpaid
 * NPSP payments (npe01__OppPayment__c).
 *
 * Paid and written-off payments are treated as history and left untouched.
 * All validation happens before any DML, so a PaymentPlanException leaves the
 * data unchanged.
 */
public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    /**
     * Replaces the unpaid, not-written-off payments of an open opportunity with
     * a monthly installment schedule.
     *
     * @param opportunityId      Opportunity to schedule.
     * @param numberOfPayments   Number of installments (must be >= 1).
     * @param firstPaymentDate   Date of the first installment; payment i (0-based)
     *                           is scheduled on firstPaymentDate.addMonths(i).
     * @return The inserted payments, in schedule order.
     * @throws PaymentPlanException if validation fails; nothing is changed.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        if (opportunityId == null) {
            throw new PaymentPlanException('An opportunity is required to schedule a payment plan.');
        }
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('The number of payments must be at least 1.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('A first payment date is required.');
        }

        List<Opportunity> opps = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            LIMIT 1
        ];
        if (opps.isEmpty()) {
            throw new PaymentPlanException('The opportunity was not found or is not accessible.');
        }
        Opportunity opp = opps[0];
        if (opp.IsClosed) {
            throw new PaymentPlanException('A payment plan cannot be scheduled for a closed opportunity.');
        }

        List<npe01__OppPayment__c> existing = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
        ];

        // Split existing payments into history (kept) and replaceable (deleted).
        Decimal settled = 0;
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c p : existing) {
            if (isHistory(p)) {
                settled += nz(p.npe01__Payment_Amount__c);
            } else {
                toDelete.add(p);
            }
        }

        Decimal outstanding = nz(opp.Amount) - settled;
        if (outstanding <= 0) {
            throw new PaymentPlanException('There is no outstanding amount left to schedule.');
        }

        // Build the new schedule before touching any data.
        Decimal count = numberOfPayments;
        Decimal installment = outstanding.divide(count, 2, System.RoundingMode.DOWN);
        Decimal allocated = 0;

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amount;
            if (i == numberOfPayments - 1) {
                // Last installment absorbs the rounding remainder.
                amount = outstanding - allocated;
            } else {
                amount = installment;
            }
            allocated += amount;

            newPayments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        // All checks passed; apply the change.
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        insert newPayments;

        return newPayments;
    }

    private static Boolean isHistory(npe01__OppPayment__c p) {
        return p.npe01__Paid__c == true || p.npe01__Written_Off__c == true;
    }

    private static Decimal nz(Decimal value) {
        return value == null ? 0 : value;
    }
}
