/**
 * Records a gift that has already been received as a Closed Won NPSP donation.
 *
 * The gift is credited to the contact's household account, the contact is the
 * primary contact holding the Donor role, every other household member holds the
 * Household Member role, and the gift has exactly one paid payment for the full
 * amount. Re-running the reconciliation never leaves duplicate roles or payments
 * on the gift, even when NPSP auto-creates roles or payments during insert.
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';
    private static final Integer MAX_OPP_NAME_LENGTH = 120;
    private static final String DATE_FORMAT = 'yyyy-MM-dd';

    /**
     * Records a Closed Won donation of {@code amount} from the contact, closed on {@code giftDate}.
     *
     * @return the Id of the new Opportunity
     * @throws IllegalArgumentException if the contact does not exist, has no household account,
     *         or if amount is null/zero/negative or giftDate is null
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        validateInputs(contactId, amount, giftDate);

        Contact donor = loadDonor(contactId);
        Id householdId = donor.AccountId;
        if (householdId == null) {
            throw new IllegalArgumentException('Contact ' + contactId + ' has no household account.');
        }

        Set<Id> householdContactIds = loadHouseholdContactIds(householdId, contactId);

        Savepoint sp = Database.setSavepoint();
        try {
            Opportunity opp = new Opportunity(
                Name = buildOpportunityName(donor, giftDate),
                AccountId = householdId,
                Amount = amount,
                CloseDate = giftDate,
                StageName = STAGE_CLOSED_WON,
                npsp__Primary_Contact__c = contactId,
                // Stop NPSP from auto-creating its own payment; we create exactly one below.
                npe01__Do_Not_Automatically_Create_Payment__c = true
            );
            insert opp;

            reconcileContactRoles(opp.Id, contactId, householdContactIds);
            reconcilePayment(opp.Id, amount, giftDate);

            return opp.Id;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }

    // ---------------------------------------------------------------------
    // Validation and lookups
    // ---------------------------------------------------------------------

    private static void validateInputs(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('contactId is required.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('amount must be a positive, non-null value.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('giftDate is required.');
        }
    }

    private static Contact loadDonor(Id contactId) {
        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            WITH USER_MODE
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact ' + contactId + ' does not exist.');
        }
        return contacts[0];
    }

    /**
     * Returns the Ids of every contact in the household, always including the donor.
     */
    private static Set<Id> loadHouseholdContactIds(Id householdId, Id donorId) {
        Set<Id> ids = new Set<Id>{ donorId };
        for (Contact c : [
            SELECT Id
            FROM Contact
            WHERE AccountId = :householdId
            WITH USER_MODE
        ]) {
            ids.add(c.Id);
        }
        return ids;
    }

    // ---------------------------------------------------------------------
    // Naming
    // ---------------------------------------------------------------------

    /**
     * Builds "<FirstName> <LastName> Donation <yyyy-MM-dd>", truncating the
     * person's name portion if needed so the result fits the 120-character limit.
     */
    private static String buildOpportunityName(Contact donor, Date giftDate) {
        String fullName = String.isBlank(donor.FirstName)
            ? donor.LastName.trim()
            : (donor.FirstName.trim() + ' ' + donor.LastName.trim());

        String suffix = ' Donation ' + DateTime.newInstanceGmt(giftDate, Time.newInstance(0, 0, 0, 0))
            .formatGmt(DATE_FORMAT);

        Integer maxNameLength = MAX_OPP_NAME_LENGTH - suffix.length();
        if (fullName.length() > maxNameLength) {
            fullName = fullName.left(maxNameLength).trim();
        }
        return fullName + suffix;
    }

    // ---------------------------------------------------------------------
    // Contact roles
    // ---------------------------------------------------------------------

    /**
     * Makes the gift's contact roles match the expected set exactly: the donor
     * holds the Donor role (primary), every other household member holds the
     * Household Member role, and no contact holds more than one role.
     * Roles that NPSP created automatically are corrected or removed.
     */
    private static void reconcileContactRoles(Id opportunityId, Id donorId, Set<Id> expectedContactIds) {
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            WITH USER_MODE
        ];

        Map<Id, OpportunityContactRole> keptByContact = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();

        for (OpportunityContactRole ocr : existingRoles) {
            if (!expectedContactIds.contains(ocr.ContactId) || keptByContact.containsKey(ocr.ContactId)) {
                // Not a household member, or a duplicate role for a contact already covered.
                rolesToDelete.add(ocr);
            } else {
                keptByContact.put(ocr.ContactId, ocr);
            }
        }

        List<OpportunityContactRole> rolesToSave = new List<OpportunityContactRole>();
        for (Id memberId : expectedContactIds) {
            Boolean isDonor = (memberId == donorId);
            String expectedRole = isDonor ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER;

            OpportunityContactRole ocr = keptByContact.get(memberId);
            if (ocr == null) {
                rolesToSave.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = memberId,
                    Role = expectedRole,
                    IsPrimary = isDonor
                ));
            } else if (ocr.Role != expectedRole || ocr.IsPrimary != isDonor) {
                ocr.Role = expectedRole;
                ocr.IsPrimary = isDonor;
                rolesToSave.add(ocr);
            }
        }

        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
        if (!rolesToSave.isEmpty()) {
            upsert rolesToSave;
        }
    }

    // ---------------------------------------------------------------------
    // Payments
    // ---------------------------------------------------------------------

    /**
     * Guarantees the gift has exactly one payment: paid, for the full amount,
     * dated giftDate. Any extra payments NPSP auto-created are removed.
     */
    private static void reconcilePayment(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Opportunity__c, npe01__Payment_Amount__c,
                   npe01__Payment_Date__c, npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
        ];

        npe01__OppPayment__c payment;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        if (payments.isEmpty()) {
            payment = new npe01__OppPayment__c(npe01__Opportunity__c = opportunityId);
        } else {
            payment = payments[0];
            for (Integer i = 1; i < payments.size(); i++) {
                paymentsToDelete.add(payments[i]);
            }
        }

        payment.npe01__Payment_Amount__c = amount;
        payment.npe01__Payment_Date__c = giftDate;
        payment.npe01__Scheduled_Date__c = giftDate;
        payment.npe01__Paid__c = true;

        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }
        upsert payment;
    }
}
