/**
 * Links parents to children in NPSP Relationships.
 *
 * NPSP (List Setting reciprocal method) automatically creates the reciprocal
 * relationship (parent -> child, typed Son/Daughter/Child via the Relationship
 * Lookup) when a relationship is inserted. Therefore only the child -> parent
 * record is inserted here; inserting the reverse as well would create duplicates.
 *
 * Bulk/governor budget for this method: 1 SOQL query and 1 DML statement.
 */
public with sharing class FamilyService {

    private static final String PARENT_TYPE = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect usable pairs: drop null entries and self-links.
        Map<Id, Id> pairs = new Map<Id, Id>();
        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            pairs.put(childId, parentId);
            childIds.add(childId);
            parentIds.add(parentId);
        }

        if (pairs.isEmpty()) {
            return;
        }

        // Single SOQL: find any existing relationship between a child and a parent, in either direction.
        Set<String> existingKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE (npe4__Contact__c IN :childIds AND npe4__RelatedContact__c IN :parentIds)
               OR (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
        ]) {
            existingKeys.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        // Skip pairs already related (either direction) and duplicate pairs within this batch,
        // including the case where the input contains both A->B and B->A.
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : pairs.keySet()) {
            Id parentId = pairs.get(childId);
            String key = pairKey(childId, parentId);
            if (!existingKeys.add(key)) {
                continue; // Set.add returns false when the key is already present
            }
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = PARENT_TYPE,
                npe4__Status__c = STATUS_CURRENT
            ));
        }

        // Single DML. NPSP creates the reciprocal records as part of this transaction.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /**
     * Order-independent key for an unordered contact pair.
     */
    private static String pairKey(Id a, Id b) {
        String sa = String.valueOf(a);
        String sb = String.valueOf(b);
        return (sa < sb) ? (sa + '|' + sb) : (sb + '|' + sa);
    }
}
