public with sharing class RecordAccessService {

    /**
     * UserRecordAccess is queried in chunks to keep each IN-filter small and
     * to stay well inside the SOQL budget: 2,000 IDs use at most 10 queries.
     */
    @TestVisible
    private static final Integer CHUNK_SIZE = 200;

    /**
     * Returns the subset of recordIds that the running user can edit, as reported
     * by UserRecordAccess.HasEditAccess. That value already accounts for object
     * permissions, ownership, sharing rules, role hierarchy, View All / Modify All,
     * and related factors.
     *
     * Null or empty input returns an empty set (never null). Null elements are ignored.
     * IDs that are not visible to the user, or that do not exist, are not returned.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        List<Id> ids = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                ids.add(recordId);
            }
        }

        if (ids.isEmpty()) {
            return editable;
        }

        Id currentUserId = UserInfo.getUserId();

        for (Integer startIndex = 0; startIndex < ids.size(); startIndex += CHUNK_SIZE) {
            Integer endIndex = Math.min(startIndex + CHUNK_SIZE, ids.size());

            List<Id> chunk = new List<Id>();
            for (Integer i = startIndex; i < endIndex; i++) {
                chunk.add(ids[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess == true) {
                    editable.add(access.RecordId);
                }
            }
        }

        return editable;
    }
}
