/**
 * Trigger Action (TAF 0.3.4) that creates an onboarding Task for the owner of a newly
 * created Account whose Type is a direct or channel customer type.
 *
 * Bulk-safe: collects all qualifying Tasks across the trigger batch and performs a single
 * insert. Performs no DML when no Account qualifies.
 *
 * Registered via Trigger_Action__mdt record TA_Account_CreateOnboardingTask (Order 10,
 * After Insert on the Account sObject_Trigger_Setting__mdt record).
 */
public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    @TestVisible
    private static final String TASK_SUBJECT = 'Onboard new customer';

    private static final Set<String> QUALIFYING_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    public void afterInsert(List<SObject> triggerNew) {
        List<Task> onboardingTasks = new List<Task>();
        Date dueDate = Date.today().addDays(7);

        for (SObject record : triggerNew) {
            Account newAccount = (Account) record;

            if (newAccount.Type == null || !QUALIFYING_TYPES.contains(newAccount.Type)) {
                continue;
            }

            onboardingTasks.add(
                new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = newAccount.Id,
                    OwnerId = newAccount.OwnerId,
                    ActivityDate = dueDate,
                    Status = 'Not Started',
                    Priority = 'Normal'
                )
            );
        }

        if (!onboardingTasks.isEmpty()) {
            insert onboardingTasks;
        }
    }
}
```

