/**
 * Imports legacy contacts without firing the welcome-task action.
 *
 * Only TA_Contact_CreateWelcomeTask is bypassed. Every other Contact action,
 * including TA_Contact_FormatPhone, still runs. The bypass is scoped to this
 * call and is cleared in a finally block, so later inserts in the same
 * transaction are unaffected.
 */
public with sharing class ContactImportService {

    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Respect a bypass the caller may already have set, and only clear what this method set.
        Boolean alreadyBypassed = MetadataTriggerHandler.isBypassed(TA_Contact_CreateWelcomeTask.class);

        if (!alreadyBypassed) {
            MetadataTriggerHandler.bypass(TA_Contact_CreateWelcomeTask.class);
        }

        try {
            insert contacts;
        } finally {
            if (!alreadyBypassed) {
                MetadataTriggerHandler.clearBypass(TA_Contact_CreateWelcomeTask.class);
            }
        }
    }
}
