```apex
public with sharing class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    // Ids collected during the current DML operation. Static, because the trigger runs once per
    // chunk (for example 200 + 50 for a 250-row insert) and each run must add to the same set.
    private static Set<Id> pendingIds = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        for (SObject record : triggerNew) {
            pendingIds.add(record.Id);
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldById = new Map<Id, SObject>(triggerOld);
        for (SObject record : triggerNew) {
            Opportunity newOpp = (Opportunity) record;
            Opportunity oldOpp = (Opportunity) oldById.get(newOpp.Id);
            if (oldOpp == null) {
                continue;
            }
            // StageName is required on Opportunity, so a null value means it was not part of this DML.
            if (newOpp.StageName != null && newOpp.StageName != oldOpp.StageName) {
                pendingIds.add(newOpp.Id);
            }
        }
    }

    // Returns the Ids collected since the last drain and clears them. Called by OpportunityErpSyncFinalizer
    // at the end of each DML operation, so every DML operation gets its own set of Ids.
    public static Set<Id> drainPendingIds() {
        Set<Id> ids = new Set<Id>(pendingIds);
        pendingIds.clear();
        return ids;
    }
}
