/**
 * Normalizes messy lead contact data on creation, before the record is saved.
 * Registered through a Trigger_Action__mdt record for the Lead before insert context.
 *
 * - Email: trims surrounding whitespace and lower-cases the value. Null stays null.
 * - Company: trims surrounding whitespace.
 * - LeadSource: defaults to 'Web' when blank. Existing values are kept.
 *
 * Changes are made in place on triggerNew, so no DML or SOQL is needed.
 */
public inherited sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        for (Lead newLead : (List<Lead>) triggerNew) {
            if (newLead.Email != null) {
                newLead.Email = newLead.Email.trim().toLowerCase();
            }

            if (newLead.Company != null) {
                newLead.Company = newLead.Company.trim();
            }

            if (String.isBlank(newLead.LeadSource)) {
                newLead.LeadSource = 'Web';
            }
        }
    }
}
