```apex
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    // Opportunities already evaluated in this transaction. TA_Opportunity_RoundAmount updates the
    // same records again, which re-runs the Opportunity trigger and every action. Only the first
    // evaluation of an Opportunity may log, so the rounding update cannot create a second task.
    private static Set<Id> evaluatedIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        for (SObject s : triggerOld) {
            oldById.put(s.Id, (Opportunity) s);
        }

        List<Task> auditTasks = new List<Task>();
        for (SObject s : triggerNew) {
            Opportunity opp = (Opportunity) s;

            // Set.add returns false when the Id was already evaluated in this transaction.
            if (!evaluatedIds.add(opp.Id)) {
                continue;
            }

            Opportunity oldOpp = oldById.get(opp.Id);
            if (oldOpp == null) {
                continue;
            }

            if (opp.Amount != oldOpp.Amount) {
                auditTasks.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = opp.Id,
                    Status = 'Completed'
                ));
            }
        }

        // One DML statement per trigger execution, regardless of batch size.
        if (!auditTasks.isEmpty()) {
            insert auditTasks;
        }
    }
}
