/**
 * Singleton that holds the parent Accounts of the Contacts in the current trigger execution.
 * The inner Service trigger action (Trigger_Action__mdt order 1, before insert) loads the map
 * once per trigger execution, so every before-insert Contact action shares one Account query.
 */
public with sharing class TA_Contact_Queries {

    private static TA_Contact_Queries instance;

    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action registered as Apex_Class_Name__c = 'TA_Contact_Queries.Service'.
     * Reloads the map on every execution because DML earlier in the same transaction
     * may involve other Accounts.
     */
    public with sharing class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (Contact con : (List<Contact>) triggerNew) {
                if (con.AccountId != null) {
                    accountIds.add(con.AccountId);
                }
            }

            TA_Contact_Queries.getInstance().accountsById = new Map<Id, Account>(
                [
                    SELECT Id, BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                    WITH USER_MODE
                ]
            );
        }
    }
}
